    #[test]
    fn while_invariant_references_const() {
        let source = r#"
            const N: i64 = 10;
            fn main() -> i64 {
              let i: i64 = 0;
              let total: i64 = 0;
              while i < N
                invariant i >= 0;
                invariant i <= N;
              {
                total = total + i;
                i = i + 1;
              }
              return total;
            }
        "#;
        compile(source).expect("while inv references const should compile");
    }

