        let source = r#"
            struct P { x: i64 }
            struct Q { y: i64 }
            methods on P {
              fn add_q(self: P, q: Q) -> i64 { return self.x + q.y; }
            }
            fn main() -> i64 {
              let p: P = P { x: 3 };
              let q: Q = Q { y: 4 };
              return p.add_q(q);
            }
        "#;
