    #[test]
    fn borrow_does_not_consume_vec() {
        let source = r#"
            fn sum(xs: ref Vec<i64>) -> i64 {
              return xs[0] + xs[1] + xs[2];
            }

            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2, 3);
              let total: i64 = sum(ref xs);
              let again: i64 = xs[0];
              assert total == 6;
              assert again == 1;
              return 0;
            }
        "#;

        compile_to_c(source).expect("borrow should not consume xs");
    }

    #[test]
    fn borrow_does_not_consume_array() {
        let source = r#"
            fn sum_four(xs: ref [i64; 4]) -> i64 {
              return xs[0] + xs[1] + xs[2] + xs[3];
            }

            fn main() -> i64 {
              let xs: [i64; 4] = [1, 2, 3, 4];
              let total: i64 = sum_four(ref xs);
              let first: i64 = xs[0];
              assert total == 10;
              assert first == 1;
              return 0;
            }
        "#;

        compile_to_c(source).expect("borrowed array stays usable");
    }

    #[test]
    fn cannot_borrow_after_move() {
        let source = r#"
            fn take(xs: Vec<i64>) -> i64 {
              return xs[0];
            }

            fn peek(xs: ref Vec<i64>) -> i64 {
              return xs[0];
            }

            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2, 3);
              let a: i64 = take(xs);
              let b: i64 = peek(ref xs);
              return a + b;
            }
        "#;

        let errors = compile(source).expect_err("borrow after move should fail");
        assert!(
            errors.iter().any(|e| e.message.contains("after it was moved")),
            "expected borrow-after-move diagnostic, got: {:?}",
            errors
        );
    }

    #[test]
    fn l4_b_let_bind_mut_ref_compiles() {
        // mut ref let-bindings work too: the binding's pointer
        // value is passed to a fn that mutates through it.
        let source = r#"
            fn push_to(xs: mut ref Vec<i64>, v: i64) -> i64 { return push(xs, v); }
            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2);
              let r: mut ref Vec<i64> = mut ref xs;
              return push_to(r, 99);
            }
        "#;
        compile(source).expect("mut ref let-binding compiles");
        compile_to_c(source).expect("C backend OK");
        compile_to_llvm(source).expect("LLVM backend OK");
    }

    #[test]
    fn l4_c_phase1_ref_return_no_ref_param_still_rejected() {
        // L4 (C) Phase 1 (2026-06-09): ref return types are now
        // accepted under the single-ref-parameter elision rule.
        // But a ref return type with ZERO ref params still
        // rejects — nothing for the returned ref to borrow from.
        let source = r#"
            struct Foo { x: i64 }
            fn escape() -> ref Foo {
              let f: Foo = Foo { x: 1 };
              let r: ref Foo = ref f;
              return r;
            }
            fn main() -> i64 { return 0; }
        "#;
        let err = compile(source).expect_err("ref return with no ref param must reject");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("no reference parameter to borrow from"),
            "expected zero-ref-param diagnostic, got: {}",
            combined
        );
    }

    #[test]
    fn l4_b_phase3_user_struct_ref_field_now_accepted() {
        // L4 (B) Phase 3 (2026-06-08): user-declared struct
        // fields can now hold ref types. The escape vector
        // (returning a struct holding a ref to a local) is
        // caught by the Stmt::Return scope-escape check (see
        // `l4_b_phase3_return_with_local_ref_in_struct_is_rejected`
        // below).
        let source = r#"
            struct Foo { x: i64 }
            struct Bag { item: ref Foo }
            fn read_bag(b: ref Bag) -> i64 { return b.item.x; }
            fn main() -> i64 {
              let f: Foo = Foo { x: 42 };
              let b: Bag = Bag { item: ref f };
              return read_bag(ref b);
            }
        "#;
        compile(source).expect("struct with ref field compiles end-to-end");
        compile_to_c(source).expect("C backend accepts");
        compile_to_llvm(source).expect("LLVM backend accepts");
    }

    #[test]
    fn l4_b_phase3_return_with_local_ref_in_struct_is_rejected() {
        // Phase 3's accompanying scope-escape check: a fn that
        // constructs a struct holding a ref to one of its own
        // locals, then returns the struct, would leak a stale
        // ref to the caller. Rejected.
        let source = r#"
            struct Foo { x: i64 }
            struct Bag { item: ref Foo }
            fn make_bag_escape() -> Bag {
              let local: Foo = Foo { x: 1 };
              return Bag { item: ref local };
            }
            fn main() -> i64 { return 0; }
        "#;
        let err = compile(source).expect_err("return with local ref must be rejected");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("escapes the function via return"),
            "expected return-escape diagnostic, got: {}",
            combined
        );
    }

    #[test]
    fn can_let_bind_reference() {
        // L4 (B) Phase 1 (2026-06-08): refs in let bindings are
        // now accepted (was: rejected with "cannot be stored in
        // 'let' bindings"). Safe under v1 because every escape
        // vector (fn return, struct field, Vec element) still
        // rejects ref types at the receiver's type check.
        let source = r#"
            struct Foo { x: i64 }
            fn read(f: ref Foo) -> i64 { return f.x; }
            fn main() -> i64 {
              let foo: Foo = Foo { x: 42 };
              let r: ref Foo = ref foo;
              return read(r);
            }
        "#;
        compile(source).expect("let-binding a ref should now compile");
        compile_to_c(source).expect("C backend accepts ref let-binding");
        compile_to_llvm(source).expect("LLVM backend accepts ref let-binding");
    }

    #[test]
    fn l4_c_phase1_multi_ref_params_return_rejected() {
        // L4 (C) Phase 3: multi-ref-param return rejects with a
        // clear "ambiguous" diagnostic suggesting refactoring.
        let source = r#"
            fn ambiguous(a: ref i64, b: ref i64) -> ref i64 {
              return a;
            }
            fn main() -> i64 { return 0; }
        "#;
        let err = compile(source).expect_err("multi-ref-param return must reject");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("2 reference parameters"),
            "expected multi-ref-param diagnostic, got: {}",
            combined
        );
        assert!(
            combined.contains("exactly one ref parameter"),
            "expected the elision-rule explanation, got: {}",
            combined
        );
    }

    #[test]
    fn l4_c_phase4_call_site_propagates_lifetime_to_dangle_check() {
        // L4 (C) Phase 4: when a fn returns a ref under elision,
        // the call-site bound `r = foo(ref X)` inherits X's
        // lifetime. Pushing r into an outer-scope Vec from a
        // deeper block must reject.
        let source = r#"
            struct P { x: i64, y: i64 }
            fn shared(p: ref P) -> ref P { return p; }
            fn main() -> i64 {
              let xs: Vec<ref P> = vec();
              {
                let inner: P = P { x: 1, y: 2 };
                let r: ref P = shared(ref inner);
                let _ = push(mut ref xs, r);
              }
              return 0;
            }
        "#;
        let err = compile(source).expect_err("inner-scope alias must reject at push");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("inner") && combined.contains("dangle"),
            "expected dangle diagnostic referencing 'inner', got: {}",
            combined
        );
    }

    #[test]
    fn l4_c_phase4_call_site_same_scope_accepts() {
        // Counterpart: same-scope `inner` & `xs` — push must
        // accept under the elision rule.
        let source = r#"
            struct P { x: i64, y: i64 }
            fn shared(p: ref P) -> ref P { return p; }
            fn main() -> i64 {
              let outer: P = P { x: 1, y: 2 };
              let xs: Vec<ref P> = vec();
              let r: ref P = shared(ref outer);
              let _ = push(mut ref xs, r);
              return 0;
            }
        "#;
        compile(source).expect("same-scope elision push must accept");
    }

    #[test]
    fn l4_c_phase1_single_ref_param_return_accepted() {
        // L4 (C) Phase 1 (2026-06-09): ref-returning fns with
        // exactly one ref parameter compile under the elision
        // rule. The returned ref's lifetime is elided to the
        // single ref parameter's lifetime.
        let source = r#"
            fn identity(xs: ref Vec<i64>) -> ref Vec<i64> {
              return xs;
            }

            fn main() -> i64 {
              return 0;
            }
        "#;

        compile(source).expect("ref return with single ref param must compile");
    }

