    #[test]
    fn big_o_classifies_self_recursion_as_recursive() {
        use crate::big_o::{analyze_function, BigO};
        let source = r#"
            fn fact(n: i64) -> i64 {
              if n <= 1 { return 1; }
              return n * fact(n - 1);
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");
        let func = checked.ir.functions.iter()
            .find(|f| f.name == "fact").expect("fn present");
        assert_eq!(analyze_function(func), BigO::Recursive);
    }

    #[test]
    fn nested_enum_payload_accepts_enum_construction() {
        // Regression: `enum Outer { Wrap(Inner) }` where Inner
        // is also an enum previously rejected `Outer.Wrap(Inner.A(42))`
        // with "enum payload must be assignable to Inner, got
        // Inner" — the parser stamps the variant's payload type
        // as `Type::Struct("Inner")` (it doesn't know Inner is
        // an enum yet), and the resolve-enum-types pass missed
        // the enum-variant payloads. Fixed 2026-06-09 by extending
        // the pass to walk every enum's variant payload list.
        let source = r#"
            enum Inner { A(i64), B }
            enum Outer { Wrap(Inner), Empty }
            fn main() -> i64 {
              let o: Outer = Outer.Wrap(Inner.A(42));
              return 0;
            }
        "#;
        compile(source).expect("nested-enum payload must accept");
    }

    #[test]
    fn explicit_drop_call_rejects_to_prevent_double_drop() {
        // Regression: explicit `r.drop()` previously compiled
        // alongside the auto-scope-exit drop, leading to a
        // double (or triple) call to the destructor — a
        // double-free in any Drop impl that touches heap state.
        // Fixed 2026-06-09 by rejecting the explicit form with
        // a "calling it manually would cause a double-drop"
        // diagnostic.
        let source = r#"
            interface Drop { fn drop(self: mut ref Self) -> i64; }
            struct R { v: i64 }
            implement Drop for R {
              fn drop(self: mut ref R) -> i64 { return self.v; }
            }
            fn main() -> i64 {
              let r: R = R { v: 42 };
              let _ = r.drop();
              return 0;
            }
        "#;
        let err = compile(source).expect_err("explicit r.drop() must reject");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("double-drop"),
            "expected double-drop diagnostic, got:\n{combined}",
        );
    }

    #[test]
    fn struct_with_enum_field_with_struct_payload_compiles_c_backend() {
        // Regression: `struct Cell { state: Status }` where
        // `enum Status { Ok(N) }` and `struct N { ... }` failed
        // the C backend with "unknown type name 'Enum_Status'"
        // (later "field 'v_Ok' has incomplete type") because the
        // C typedef ordering had no topo sort across structs +
        // payloaded enums.
        // Fixed 2026-06-09: forward-declare struct names at the
        // top, then unify the topo loop to emit deferred enums
        // alongside structs + Vec bundles. Enum waits on its
        // by-value struct payload deps; struct waits on its
        // by-value enum field deps.
        let source = r#"
            enum Status { Ok(N), Err(i64) }
            struct N { v: i64 }
            struct Cell { state: Status }
            fn main() -> i64 {
              let c: Cell = Cell { state: Status.Ok(N { v: 42 }) };
              return 0;
            }
        "#;
        compile_to_c(source).expect("struct + enum + struct chain must compile on C backend");
        compile_to_llvm(source).expect("same on LLVM backend (was already passing)");
    }

    #[test]
    fn unsafe_block_with_return_satisfies_must_return() {
        // Regression: `unsafe(reason = "...") { return X; }` as
        // the function body previously failed the "fn must return
        // T" check because the inner termination flag wasn't
        // propagated up. Fixed 2026-06-09.
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn doit() -> i64 {
              unsafe(reason = "nested in fn") {
                return 1;
              }
            }
            fn main() -> i64 { return doit(); }
        "#;
        compile(source).expect("return inside unsafe must satisfy fn-must-return");
    }

    #[test]
    fn async_fn_returning_ref_to_user_struct_compiles_on_c_backend() {
        // Regression: an async fn returning `ref T` where T is a
        // user-defined struct synthesizes `Future__Ref_Struct__T`
        // whose payload is `const Struct_T*`. The C backend's
        // pre-emit pass for payloaded enums emitted that typedef
        // BEFORE Struct_T was declared (cc: "unknown type name
        // 'Struct_T'"). LLVM compiled cleanly. Fixed 2026-06-09
        // by deferring the pre-emit for enums whose payload
        // references a user struct (directly or via Vec / Array /
        // Ref / RefMut / Box / Tuple).
        let source = r#"
            struct P { x: i64 }
            async fn pass(p: ref P) -> ref P { return p; }
            fn main() -> i64 { return 0; }
        "#;
        compile_to_c(source).expect("async ref-return must compile on C backend");
        compile_to_llvm(source).expect("async ref-return must compile on LLVM backend");
    }

    #[test]
    fn vec_of_box_compiles_on_both_backends() {
        // Regression: `Vec<Box<T>>` previously panicked both
        // backends. C: `intent_vec_/*_Box<T>_*/__from(...)`
        // — placeholder identifier broke cc. LLVM:
        // `llvm_type: use llvm_type_string for aggregate / ref
        // type Box(I64)`. Fixed 2026-06-09: element_tag and
        // vec_struct_tag now recursively spell Box as
        // `box_<inner_tag>` so per-shape Vec typedefs come out
        // identifier-safe.
        let source = r#"
            struct Container { items: Vec<Box<i64>> }
            fn main() -> i64 {
              let c: Container = Container {
                items: vec(box(1), box(2), box(3)),
              };
              return len(c.items) as i64;
            }
        "#;
        compile_to_c(source).expect("Vec<Box<i64>> must compile (C)");
        compile_to_llvm(source).expect("Vec<Box<i64>> must compile (LLVM)");
    }

    #[test]
    fn vec_of_box_llvm_emits_per_element_free_loop() {
        // Regression: LLVM backend's Vec<Box<T>>__free was missing
        // the Box arm, so Box-element heap allocations were leaked
        // on every Vec drop. Fixed 2026-06-10: Type::Box arm added
        // to emit_vec_helpers. Verify the __free function contains
        // a loop (fr_check label) and a @free call for the Box pointer.
        let source = r#"
            fn main() -> i64 {
              let xs: Vec<Box<i64>> = vec(box(1), box(2), box(3));
              return len(xs) as i64;
            }
        "#;
        let ll = compile_to_llvm(source).expect("Vec<Box<i64>> LLVM compile");
        assert!(
            ll.contains("fr_check:"),
            "expected per-element free loop (fr_check label) in Vec<Box<i64>>__free:\n{}",
            &ll[..ll.len().min(3000)]
        );
        assert!(
            ll.contains("call void @free"),
            "expected @free call inside Vec<Box<i64>>__free loop:\n{}",
            &ll[..ll.len().min(3000)]
        );
    }

    #[test]
    fn vec_of_box_dyn_iface_llvm_uses_correct_element_size() {
        // Regression: vec_element_byte_size returned 8 for ALL Box<T>,
        // but Box<dyn Iface> stores a 16-byte fat-pointer struct inline.
        // This caused Vec<Box<dyn Iface>> to allocate 8-byte slots and
        // corrupt heap on every push. Fixed 2026-06-10 by adding a
        // Box(Object) => 16 arm to vec_element_byte_size.
        let source = r#"
            struct Circle { r: i64 }
            interface Renderer { fn render(self: Circle) -> i64; }
            implement Renderer for Circle {
              fn render(self: Circle) -> i64 { return self.r * 2; }
            }
            fn main() -> i64 {
              let xs: Vec<Box<dyn Renderer>> = vec(box(Circle { r: 1 } as dyn Renderer));
              return 0;
            }
        "#;
        let ll = compile_to_llvm(source).expect("Vec<Box<dyn Renderer>> compiles");
        // Buffer must allocate 16 bytes per slot (not 8)
        assert!(
            ll.contains("mul i64 %new_cap_g, 16") || ll.contains("mul i64 %new_cap_gm, 16"),
            "Vec<Box<dyn Iface>> push must allocate 16 bytes/slot (fat-ptr size):\n{}",
            &ll[..ll.len().min(3000)]
        );
        // The __free must loop and free each element's .data field
        assert!(
            ll.contains("fr_check:"),
            "Vec<Box<dyn Iface>>__free must contain per-element drop loop:\n{}",
            &ll[..ll.len().min(3000)]
        );
        assert!(
            ll.contains("extractvalue %intent_dyn_Renderer"),
            "Vec<Box<dyn Iface>>__free must extractvalue from fat-ptr element:\n{}",
            &ll[..ll.len().min(3000)]
        );
    }

    #[test]
    fn closure_inside_iface_impl_method_lifts_correctly() {
        // Regression: an inline `fn(x: i64) -> i64 { ... }`
        // closure inside an `implement Iface for T { fn m(...) }`
        // method body previously panicked the checker with
        // "internal: anonymous fn expression survived the
        // lambda-lift pass. This is a vāṇी compiler bug —
        // please report." The lambda_lift_program pass walked
        // only program.functions; impls were hoisted INTO
        // functions later but never had their closures lifted.
        // Fixed 2026-06-09 by lifting closures inside
        // methods_blocks + impls BEFORE the hoist pass runs.
        let source = r#"
            interface Counter { fn tick(self: ref Self) -> i64; }
            struct C { n: i64 }
            implement Counter for C {
              fn tick(self: ref C) -> i64 {
                let f = fn(x: i64) -> i64 { return x + 1; };
                return f(self.n);
              }
            }
            fn main() -> i64 {
              let c: C = C { n: 41 };
              return c.tick();
            }
        "#;
        compile(source).expect("closure-in-impl must lift");
    }

    #[test]
    fn closure_inside_methods_block_method_lifts_correctly() {
        // Parallel regression for `methods on T { fn m(...) }`
        // blocks. Same fix path; covered as a separate test
        // so the methods-block + impl branches stay
        // independently pinned.
        let source = r#"
            struct Calc { base: i64 }
            methods on Calc {
              fn double(self: ref Calc) -> i64 {
                let f = fn(x: i64) -> i64 { return x + x; };
                return f(self.base);
              }
            }
            fn main() -> i64 {
              let c: Calc = Calc { base: 21 };
              return c.double();
            }
        "#;
        compile(source).expect("closure-in-methods-block must lift");
    }

    #[test]
    fn box_dyn_iface_accepts_inline_struct_literal_source() {
        // Regression: `box(Circle { r: 5 } as dyn Drawable)`
        // with an inline struct literal previously panicked both
        // backends ("Box<dyn Iface> __box_new expected a
        // DynCoerce arg; got Block { ... }"). The checker
        // hoists the concrete into a synthetic let inside a
        // Block; the codegen now unwraps the Block before
        // extracting the DynCoerce. Fixed 2026-06-09.
        let source = r#"
            interface Drawable {
              fn area(self: ref Self) -> i64;
            }
            struct Circle { r: i64 }
            implement Drawable for Circle {
              fn area(self: ref Circle) -> i64 { return self.r * self.r * 3; }
            }
            fn main() -> i64 {
              let b: Box<dyn Drawable> = box(Circle { r: 5 } as dyn Drawable);
              return 0;
            }
        "#;
        compile_to_c(source).expect("inline box(Foo {} as dyn Iface) must compile (C)");
        compile_to_llvm(source).expect("inline box(Foo {} as dyn Iface) must compile (LLVM)");
    }

    #[test]
    fn big_o_bounded_for_loop_constants_stays_constant() {
        // L4 (D) refinement: `for i from 0 to 16` is bounded —
        // the analyzer should NOT bump it to O(n) since the
        // iteration count is fixed at 16.
        use crate::big_o::{analyze_function, BigO};
        let source = r#"
            fn bounded_loop() -> i64 {
              let total: i64 = 0;
              for i from 0 to 16 {
                let _ = i;
              }
              return total;
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");
        let func = checked.ir.functions.iter()
            .find(|f| f.name == "bounded_loop").expect("fn present");
        assert_eq!(analyze_function(func), BigO::Constant);
    }

    #[test]
    fn big_o_cross_fn_propagation_through_nested_call() {
        // L4 (D) refinement: a fn that calls an O(n log n)
        // helper inside an O(n) loop ships as O(n² log n).
        use crate::big_o::{annotate_program, BigOMode};
        let source = r#"
            fn helper(xs: Vec<i64>) -> Vec<i64> {
              let ys: Vec<i64> = xs;
              let _ = sort(mut ref ys);
              return ys;
            }
            fn caller() -> i64 {
              let ys: Vec<i64> = vec(3, 1, 2);
              let n: i64 = len(ys) as i64;
              let i: i64 = 0;
              while i < n {
                let _ = helper(vec(1, 2, 3));
                i = i + 1;
              }
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");
        let annotations = annotate_program(&checked.ir, BigOMode::Force);
        let caller = annotations.iter()
            .find(|(n, _)| n == "caller")
            .expect("caller in annotations");
        // Without propagation this would report O(n); with
        // propagation it's at least O(n² log n) since the
        // n log n helper runs inside an n-loop.
        let s = format!("{}", caller.1);
        assert!(
            s.contains("log n") && (s.contains("n²") || s.contains("n^")),
            "expected n^? log n classification, got: {}",
            s,
        );
    }

    #[test]
    fn big_o_mutual_recursion_marks_both_as_recursive() {
        // L4 (D) refinement: an SCC of size > 1 (mutual
        // recursion) flags every member as Recursive.
        use crate::big_o::{annotate_program, BigO, BigOMode};
        let source = r#"
            fn a(n: i64) -> i64 {
              if n <= 0 { return 0; }
              return b(n - 1);
            }
            fn b(n: i64) -> i64 {
              if n <= 0 { return 0; }
              return a(n - 1);
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");
        let annotations = annotate_program(&checked.ir, BigOMode::Force);
        for name in ["a", "b"] {
            let entry = annotations.iter()
                .find(|(n, _)| n == name)
                .expect(name);
            assert_eq!(
                entry.1, BigO::Recursive,
                "{} should be Recursive (mutual recursion SCC), got {:?}",
                name, entry.1,
            );
        }
    }

    #[test]
    fn big_o_array_for_loop_bounded_constant() {
        // L4 (D) refinement: `for x in ref [T; N]` is bounded —
        // N is fixed in the type. The analyzer should NOT bump
        // it to O(n).
        use crate::big_o::{analyze_function, BigO};
        let source = r#"
            fn array_sum() -> i64 {
              let xs: [i64; 4] = [1, 2, 3, 4];
              let total: i64 = 0;
              for v in ref xs {
                let _ = v;
              }
              return total;
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");
        let func = checked.ir.functions.iter()
            .find(|f| f.name == "array_sum").expect("fn present");
        assert_eq!(analyze_function(func), BigO::Constant);
    }

    #[test]
    fn big_o_auto_mode_skips_constant_fns_but_force_includes_them() {
        use crate::big_o::{annotate_program, BigOMode};
        let source = r#"
            fn trivial(x: i64) -> i64 { return x + 1; }
            fn one_loop(xs: Vec<i64>) -> i64 {
              let n: i64 = len(xs) as i64;
              let i: i64 = 0;
              while i < n { i = i + 1; }
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles");

        let auto = annotate_program(&checked.ir, BigOMode::Auto);
        // Auto skips O(1): only one_loop should be in the list.
        assert_eq!(auto.len(), 1);
        assert_eq!(auto[0].0, "one_loop");

        let force = annotate_program(&checked.ir, BigOMode::Force);
        // Force includes every fn including main + trivial.
        assert_eq!(force.len(), 3);
        let names: Vec<&str> = force.iter().map(|p| p.0.as_str()).collect();
        assert!(names.contains(&"trivial"));
        assert!(names.contains(&"one_loop"));
        assert!(names.contains(&"main"));

        let off = annotate_program(&checked.ir, BigOMode::Off);
        assert!(off.is_empty());
    }

    #[test]
    fn elaboration_renders_after_move_after_use_diagnostic() {
        // User-direction item (2026-06-08): the move-after-use
        // diagnostic carries a 3-step elaboration explaining
        // affine ownership in concrete terms. The renderer
        // emits the steps as "help: 1." / "help: 2." / "help:
        // 3." lines after the primary + related notes.
        use crate::diagnostic::format_diagnostics;
        let source = r#"fn take(xs: Vec<i64>) -> i64 { return xs[0]; }
fn main() -> i64 {
  let xs: Vec<i64> = vec(1, 2, 3);
  let _ = take(xs);
  return xs[0];
}
"#;
        let errors = compile(source).expect_err("use-after-move");
        let rendered = format_diagnostics("t.vani", source, &errors);
        assert!(
            rendered.contains("help: 1."),
            "expected step-1 help line, got:\n{rendered}"
        );
        assert!(
            rendered.contains("help: 2."),
            "expected step-2 help line, got:\n{rendered}"
        );
        assert!(
            rendered.contains("help: 3."),
            "expected step-3 help line, got:\n{rendered}"
        );
        assert!(
            rendered.contains("affine ownership"),
            "expected the WHY step to mention affine ownership, got:\n{rendered}"
        );
        assert!(
            rendered.contains(".clone()"),
            "expected the HOW step to mention the .clone() option, got:\n{rendered}"
        );
    }

