    /// Arc 8 v3.1 Phase 4a-narrow — nested async (Task__X
    /// auto-registered as a struct type so other async fns can
    /// declare a local of that type). Validates the infrastructure
    /// shipped this slice. Full `await sub` semantic sugar is
    /// Phase 4a-broad.
    #[test]
    fn v31_phase4a_nested_async_task_local_accepted() {
        let source = r#"
            async fn inner(fd: i64) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n * 100;
            }

            async fn outer(fd: i64) -> i64 {
              let sub: Task__inner = inner(fd);
              let p: i64 = __poll_inner(mut ref sub);
              let _ = io_recv_async(fd, 0);
              return p;
            }
            fn main() -> i64 { return 0; }
        "#;
        let c = compile_to_c(source).expect("Phase 4a-narrow must compile on C");
        let ll = compile_to_llvm(source).expect("Phase 4a-narrow must compile on LLVM");
        assert!(c.contains("Task__inner") && c.contains("Task__outer"));
        assert!(c.contains("__poll_inner") && c.contains("__poll_outer"));
        assert!(ll.contains("Task__inner") && ll.contains("Task__outer"));
    }

    /// Arc 8 v3.1 Phase 4a-broad — `__poll_X(mut ref sub)`
    /// recognized as a suspend point. The outer's state machine
    /// emits the Seg::Suspend pattern (Pending yields outer;
    /// Error propagates; otherwise stores value + advances state).
    /// User-facing pattern: `let n: i64 = __poll_inner(mut ref
    /// sub);` is the equivalent of `await sub` in other languages.
    #[test]
    fn v31_phase4b_await_sub_as_suspend_point() {
        let source = r#"
            async fn inner(fd: i64) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n * 100;
            }

            async fn outer(fd: i64) -> i64 {
              let sub: Task__inner = inner(fd);
              let result: i64 = __poll_inner(mut ref sub);
              return result + 1;
            }
            fn main() -> i64 { return 0; }
        "#;
        let c = compile_to_c(source).expect("Phase 4b must compile on C");
        let ll = compile_to_llvm(source).expect("Phase 4b must compile on LLVM");
        // The outer's poll fn should include the Pending-yield
        // pattern around the __poll_inner call.
        assert!(
            c.contains("__poll_inner") && c.contains("Task__outer"),
            "C output should include both __poll_inner call site + outer task struct"
        );
        assert!(ll.contains("Task__outer"));
    }

    /// Arc 8 v3.1 Phase 4a-broad — an async fn whose body has
    /// ONLY a __poll_X call (no other suspends) still triggers
    /// the v3.1 transform. body_uses_io_async recognizes the
    /// __poll_ prefix.
    #[test]
    fn v31_phase4b_async_with_only_poll_call_still_v31() {
        let source = r#"
            async fn inner(fd: i64) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n;
            }

            async fn outer(fd: i64) -> i64 {
              let sub: Task__inner = inner(fd);
              let result: i64 = __poll_inner(mut ref sub);
              return result;
            }
            fn main() -> i64 { return 0; }
        "#;
        let c = compile_to_c(source).expect("Phase 4b must compile on C");
        // Outer should be transformed into a Task__outer + poll
        // fn (NOT a Future__i64). Check the task struct exists.
        assert!(
            c.contains("Task__outer") && c.contains("__poll_outer"),
            "outer should be v3.1-transformed when body only has __poll_X (no io_*_async)"
        );
    }

    /// Arc 8 v3.1 Phase 4b — multi-task: an outer async fn can
    /// construct + await MULTIPLE sub-tasks. Ships no compiler
    /// changes; verifies Phase 4a-broad scales beyond one
    /// sub-task per outer.
    #[test]
    fn v31_phase4b_multitask_accepted() {
        let source = r#"
            async fn fetch_one(fd: i64) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n;
            }

            async fn outer(fd1: i64, fd2: i64) -> i64 {
              let sub1: Task__fetch_one = fetch_one(fd1);
              let sub2: Task__fetch_one = fetch_one(fd2);
              let r1: i64 = __poll_fetch_one(mut ref sub1);
              let r2: i64 = __poll_fetch_one(mut ref sub2);
              return r1 + r2;
            }
            fn main() -> i64 { return 0; }
        "#;
        let c = compile_to_c(source).expect("Phase 4b multi-task must compile on C");
        let ll = compile_to_llvm(source).expect("Phase 4b multi-task must compile on LLVM");
        // outer's task struct should contain sub1 + sub2 fields
        // of type Task__fetch_one.
        assert!(c.contains("Task__outer") && c.contains("Task__fetch_one"));
        assert!(c.contains("sub1") && c.contains("sub2"));
        assert!(ll.contains("Task__outer"));
    }

    /// Arc 8 v3.1 Phase 4c-broad — generic async fns now compile
    /// end-to-end. The validator accepts `Type::Param` in params
    /// + return types when the enclosing fn declares the type
    /// param; mono specializes the synthesized Task struct and
    /// poll fn per concrete T; `infer_concrete_type_for_call`
    /// finds the T-bearing slot in the called fn's signature
    /// and structurally unwraps `mut ref Task__X<T>` patterns
    /// for v3.1 `__poll_*` calls.
    #[test]
    fn v31_phase4c_broad_generic_async_fn_compiles_and_specializes() {
        let source = r#"
            async fn identity<T>(fd: i64, x: T) -> T {
              let n: i64 = io_recv_async(fd, 64);
              return x;
            }

            fn drive(ep: i64, t: mut ref Task__identity<i64>) -> i64 {
              while true {
                let r: i64 = __poll_identity(t);
                if r != 0 - 2 { return r; }
                let _ = epoll_wait_one(ep, 0);
              }
              return 0;
            }

            fn main() -> i64 {
              let server: i64 = tcp_listen(0);
              let t: Task__identity<i64> = identity(server, 42);
              let _ = tcp_close(server);
              return 0;
            }
        "#;
        let c = compile_to_c(source)
            .expect("Phase 4c-broad: generic async fn must compile via C backend");
        // The C output must include the SPECIALIZED struct +
        // poll fn names (mangled with the concrete T=i64).
        assert!(
            c.contains("Task__identity__i64"),
            "expected mangled Task__identity__i64 in C output"
        );
        assert!(
            c.contains("fn___poll_identity__i64") || c.contains("__poll_identity__i64"),
            "expected mangled __poll_identity__i64 in C output"
        );
        // The __result field carries the generic return value.
        assert!(
            c.contains("__result"),
            "expected __result field in specialized Task struct"
        );
    }

    /// C backend regression: Vec<UserStruct> as a struct field
    /// (e.g. `struct Holder { items: Vec<Point> }`). Pre-existing
    /// bug fix 2026-06-06 — Vec bundle for Struct_Point referenced
    /// Struct_Point* + sizeof(Struct_Point) before Struct_Point's
    /// typedef. Unified topological emit (Vec<primitive> → struct
    /// deps → Vec<UserStruct> → structs that use Vec<UserStruct>)
    /// resolves it. LLVM backend handles this via forward-declared
    /// named types so it didn't break there; only C needed the fix.
    #[test]
    fn c_backend_vec_of_user_struct_in_struct_field() {
        let source = r#"
            struct Point { x: i64, y: i64 }
            struct Holder { ps: Vec<Point> }

            fn main() -> i64 {
              let h: Holder = Holder {
                ps: vec(Point { x: 1, y: 10 }, Point { x: 2, y: 20 })
              };
              print "ok:", h.ps[1].x;
              return 0;
            }
        "#;
        let c = compile_to_c(source).expect("Vec<Struct> in struct field must compile on C");
        let ll = compile_to_llvm(source).expect("Vec<Struct> in struct field must compile on LLVM");
        // The C output must contain the Vec<Point> bundle typedef
        // AFTER the Struct_Point typedef. Verify both are present;
        // ordering is enforced by the topo sort but the parity
        // sweep catches actual runtime correctness.
        assert!(c.contains("Struct_Point") && c.contains("intent_vec_Struct_Point"));
        assert!(ll.contains("Struct_Point"));
    }

    /// LLVM backend: divide-by-zero check + match-arm phi
    /// interaction (the `div_ok` block must be tracked as the
    /// predecessor in surrounding phi merges, not the
    /// `match_arm_<N>` label). Without the
    /// `ctx.current_block = ok` update after the div safety
    /// check, the phi attaches the sdiv result to the wrong
    /// predecessor block and LLVM's module verifier rejects
    /// the IR ("Bad module").
    ///
    /// Reproducer is non-async (the bug pre-existed Phase 4)
    /// and surfaces in any match whose arm contains a
    /// safety-checked div/rem (or shift). Pinned via a string
    /// search on the emitted IR.
    #[test]
    fn llvm_match_arm_div_phi_uses_correct_predecessor() {
        let source = r#"
            enum Mode { Normal, Eager, Lazy }

            fn classify(m: Mode, n: i64) -> i64 {
              return match m {
                Mode.Normal then n,
                Mode.Eager then n * 10,
                Mode.Lazy then n / 2
              };
            }

            fn main() -> i64 { return classify(Mode.Eager, 2); }
        "#;
        let ll = compile_to_llvm(source).expect("must compile");
        // The phi at match_merge0 should NOT name `match_arm_24`
        // (the arm's opening block) as the predecessor for the
        // div result. After the fix, the sdiv produces its
        // value in `div_ok<N>` so that label should appear in
        // the phi instead.
        assert!(
            !ll.contains("phi i64 [ %t1, %match_arm_02 ], [ %t3, %match_arm_13 ], [ %t6, %match_arm_24 ]"),
            "regression: phi uses match_arm_24 instead of div_ok block"
        );
        // The sdiv must be emitted (no other regression masking the fix).
        assert!(ll.contains("sdiv"), "expected sdiv emit");
    }

    /// Arc 8 v3.1 Phase 4a-narrow — without auto-registration the
    /// Task__X type wouldn't pass the v3.1 locals gate. Verify
    /// the gate diagnostic mentions registered Struct.
    #[test]
    fn v31_phase4a_unregistered_task_type_local_rejected() {
        // A hypothetical bare "Task__nonexistent" with no
        // corresponding async fn is treated as an unregistered
        // Struct name, so the v3.1 gate rejects it.
        let source = r#"
            async fn outer(fd: i64) -> i64 {
              let sub: Task__nonexistent = 0;
              let n: i64 = io_recv_async(fd, 64);
              return n;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errors = compile(source).expect_err(
            "unregistered Task__X type must be rejected"
        );
        assert!(
            errors.iter().any(|e| {
                let m = e.message.as_str();
                m.contains("Task__nonexistent") || m.contains("Struct")
                    || m.contains("registered")
            }),
            "expected unregistered-struct diagnostic; got: {:?}",
            errors.iter().map(|e| e.message.as_str()).collect::<Vec<_>>()
        );
    }

