    #[test]
    fn box_i64_alloc_unbox_compiles() {
        // L2 Phase 1 (2026-06-07): Box<i64> heap allocation via
        // box(x), readback via unbox(ref b), implicit free at
        // scope exit. All three paths through the C backend.
        let source = r#"
            fn main() -> i64 {
              let b: Box<i64> = box(42);
              let v: i64 = unbox(ref b);
              print v;
              return 0;
            }
        "#;
        crate::compile(source).expect("Box<i64> basic round-trip compiles");
    }

    #[test]
    fn box_bool_alloc_unbox_compiles() {
        // L2 Phase 1: Box<bool> — Copy primitive other than i64.
        let source = r#"
            fn main() -> i64 {
              let b: Box<bool> = box(true);
              let v: bool = unbox(ref b);
              if v { return 1; }
              return 0;
            }
        "#;
        crate::compile(source).expect("Box<bool> compiles");
    }

    #[test]
    fn box_copy_struct_compiles() {
        // L2 Phase 1: Box<MyStruct> where the struct is Copy.
        // Verifies the struct's storage spelling (Struct_Name)
        // flows through __box_new's malloc/sizeof.
        let source = r#"
            struct Point { x: i64, y: i64 }
            fn main() -> i64 {
              let p: Point = Point { x: 3, y: 4 };
              let b: Box<Point> = box(p);
              let got: Point = unbox(ref b);
              return got.x + got.y;
            }
        "#;
        crate::compile(source).expect("Box<Copy struct> compiles");
    }

    #[test]
    fn box_in_struct_field_compiles_and_frees() {
        // L2 Phase 1: the documented blocker case. A struct
        // field of type Box<i64> stores a heap pointer; the
        // outer struct's scope-exit drop chains into the
        // Box field's free(), no leak.
        let source = r#"
            struct Holder { b: Box<i64> }
            fn main() -> i64 {
              let h: Holder = Holder { b: box(99) };
              let v: i64 = unbox(ref h.b);
              return v;
            }
        "#;
        crate::compile(source).expect("Box<i64> as struct field compiles");
    }

    #[test]
    fn box_llvm_codegen_emits_malloc_store_free() {
        // L2 Phase 2 (2026-06-07): LLVM backend codegens Box<T>
        // for Copy + sized inner types. Pin the IR shape so
        // future refactors notice if the heap-alloc / store /
        // free trio drifts.
        let source = r#"
            fn main() -> i64 {
              let b: Box<i64> = box(42);
              let v: i64 = unbox(ref b);
              return v;
            }
        "#;
        let ir = compile_to_llvm(source).expect("Box<i64> LLVM codegen");
        assert!(ir.contains("call i8* @malloc"), "expected @malloc call in IR: {}", ir);
        assert!(ir.contains("call void @free"), "expected @free call in IR: {}", ir);
        assert!(ir.contains("bitcast i8*"), "expected bitcast i8* in IR: {}", ir);
    }

    #[test]
    fn box_llvm_struct_field_storage_compiles() {
        // L2 Phase 2: Box as a struct field also reaches LLVM
        // codegen (uniform scalar Let path + struct typedef
        // with T* field).
        let source = r#"
            struct Holder { b: Box<i64> }
            fn main() -> i64 {
              let h: Holder = Holder { b: box(99) };
              let v: i64 = unbox(ref h.b);
              return v;
            }
        "#;
        compile_to_llvm(source).expect("Box<i64> as struct field LLVM-compiles");
    }

    #[test]
    fn box_dyn_iface_construction_compiles() {
        // L2 Phase 3 (2026-06-08): `Box<dyn Iface>` heap-allocates
        // a concrete value and wraps it in an owning fat pointer
        // { vtable, heap_data_ptr }. The local IS the 16-byte
        // fat pointer struct, NOT a pointer to one. Drop frees
        // `.data` (the heap concrete).
        let source = r#"
            struct Circle { r: i64 }
            interface Drawable { fn area(self: Circle) -> i64; }
            implement Drawable for Circle {
              fn area(self: Circle) -> i64 { return self.r * self.r; }
            }
            fn main() -> i64 {
              let c: Circle = Circle { r: 6 };
              let b: Box<dyn Drawable> = box(c as dyn Drawable);
              return 0;
            }
        "#;
        crate::compile(source).expect("Box<dyn Iface> basic compile");
    }

    #[test]
    fn box_dyn_iface_method_dispatch_through_ref() {
        // L2 Phase 3: method dispatch through `ref Box<dyn Iface>`.
        // The checker treats Box<dyn Iface> the same as plain
        // `dyn Iface` for method-call receivers — the underlying
        // fat pointer is identical in layout, only the data slot
        // ownership differs.
        let source = r#"
            struct Circle { r: i64 }
            interface Drawable { fn area(self: Circle) -> i64; }
            implement Drawable for Circle {
              fn area(self: Circle) -> i64 { return self.r * self.r; }
            }
            fn area_of_box(b: ref Box<dyn Drawable>) -> i64 {
              return b.area();
            }
            fn main() -> i64 {
              let c: Circle = Circle { r: 7 };
              let b: Box<dyn Drawable> = box(c as dyn Drawable);
              let a: i64 = area_of_box(ref b);
              return a;
            }
        "#;
        crate::compile(source).expect("Box<dyn> method dispatch compile");
    }

    #[test]
    fn box_dyn_iface_in_struct_field_unblocks_l2() {
        // L2 Phase 3 — the originally documented L2 blocker case:
        // `struct Drawer { r: Box<dyn Renderer> }`. The outer
        // struct's scope-exit drop chains into the Box<dyn>
        // field's `.data` free.
        let source = r#"
            struct Circle { r: i64 }
            interface Renderer { fn render(self: Circle) -> i64; }
            implement Renderer for Circle {
              fn render(self: Circle) -> i64 { return self.r * 2; }
            }
            struct Drawer { rend: Box<dyn Renderer> }
            fn main() -> i64 {
              let c: Circle = Circle { r: 5 };
              let d: Drawer = Drawer { rend: box(c as dyn Renderer) };
              return d.rend.render();
            }
        "#;
        crate::compile(source).expect("Box<dyn> as struct field — L2 blocker — compiles");
    }

    #[test]
    fn box_accepts_vec_and_owned_str_with_recursive_drop() {
        // L2 follow-up (2026-06-08): Box<Vec<T>> and Box<OwnedStr>
        // are now accepted. The box() builtin marks the source
        // var as moved (so its own scope-exit Drop is suppressed),
        // and the scope-exit drop for Box<Vec<T>> / Box<OwnedStr>
        // chains into the inner type's Drop before freeing the
        // box's own heap slot. Replaces the prior gating-test.
        let source = r#"
            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2, 3);
              let b: Box<Vec<i64>> = box(xs);
              let s: OwnedStr = "a" + "b";
              let bs: Box<OwnedStr> = box(s);
              return 0;
            }
        "#;
        crate::compile(source).expect("Box<Vec<i64>> + Box<OwnedStr> compile after follow-up");
        crate::compile_to_c(source).expect("C backend accepts Box<Vec<T>> + Box<OwnedStr>");
        crate::compile_to_llvm(source).expect("LLVM backend accepts Box<Vec<T>> + Box<OwnedStr>");
    }

    #[test]
    fn box_value_infers_dyn_iface_cast_from_annotation() {
        // L2 follow-up (2026-06-08): `let b: Box<dyn Iface> = box(value);`
        // — the explicit `as dyn Iface` cast is no longer required.
        // The checker's `try_elaborate_box_to_dyn` pre-pass synthesizes
        // the same DynCoerce node the explicit form produces.
        let source = r#"
            struct Circle { r: i64 }
            interface Drawable { fn area(self: Circle) -> i64; }
            implement Drawable for Circle {
              fn area(self: Circle) -> i64 { return self.r * self.r; }
            }
            fn main() -> i64 {
              let c: Circle = Circle { r: 7 };
              let b: Box<dyn Drawable> = box(c);
              return 0;
            }
        "#;
        crate::compile(source).expect("box(value) sugar compiles");
        crate::compile_to_c(source).expect("box(value) sugar on C");
        crate::compile_to_llvm(source).expect("box(value) sugar on LLVM");
    }

    #[test]
    fn mandarin_pragma_compiles_and_runs() {
        // Phase 10.2 (2026-06-08): Mandarin Chinese — first
        // pure-Han keyword dialect. Shares Script::Japanese with
        // Japanese for the purity gate; pragma + keyword table
        // disambiguate. Japanese keywords mix Kanji+Hiragana
        // (関数 / もし); Mandarin keywords are pure-Han
        // (函数 / 如果).
        let source = "// vani-lang: mandarin\n\
                      目的 \"basic Mandarin demo\";\n\
                      函数 add(a: i64, b: i64) -> i64 {\n  \
                        返回 a + b;\n\
                      }\n\
                      函数 main() -> i64 {\n  \
                        让 x: i64 = add(20, 22);\n  \
                        断言 x == 42;\n  \
                        打印 x;\n  \
                        返回 0;\n\
                      }\n";
        crate::compile(source).expect("Mandarin basics compile");
        crate::compile_to_c(source).expect("C backend accepts Mandarin");
        crate::compile_to_llvm(source).expect("LLVM backend accepts Mandarin");
    }

    #[test]
    fn mandarin_pragma_disambiguates_from_japanese() {
        // Both dialects share Script::Japanese (CJK Unified
        // Ideographs are common to both). The dispatch order
        // routes Japanese first; Mandarin's pure-Han keywords
        // are distinct strings that fall through. Verify:
        // Mandarin `函数` is fn under mandarin pragma, but
        // raw `関数` is fn under japanese pragma. Each rejects
        // the other's spelling cleanly.
        let mandarin_source =
            "// vani-lang: mandarin\n函数 main() -> i64 { 返回 0; }\n";
        crate::compile(mandarin_source).expect("Mandarin 函数 compiles");
        let japanese_source =
            "// vani-lang: japanese\n関数 main() -> i64 { 戻る 0; }\n";
        crate::compile(japanese_source).expect("Japanese 関数 still compiles");
    }

    #[test]
    fn ref_canceltoken_param_in_v31_async_fn_compiles() {
        // A4.4 (2026-06-08): `ref CancelToken` is now accepted
        // as a v3.1 async-fn parameter. The synthesized Task
        // struct carries it as a `const Struct_CancelToken*`
        // field; the body's `token.cancelled` reads compile to
        // `self->token->cancelled` via existing ref-deref paths.
        let source = r#"
            async fn fetcher(fd: i64, token: ref CancelToken) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n;
            }
            fn main() -> i64 { return 0; }
        "#;
        crate::compile(source).expect("ref CancelToken param compiles");
        crate::compile_to_c(source).expect("C backend accepts ref CancelToken");
        crate::compile_to_llvm(source).expect("LLVM backend accepts ref CancelToken");
    }

    #[test]
    fn a44_auto_injects_cancel_guard_before_suspend() {
        // A4.4 auto-plumbing: when an async fn has a
        // `ref CancelToken` param + i64 return, the v3.1
        // transform injects `if token.cancelled { return 0 - 1; }`
        // before each suspend point. Verify by emitting C and
        // looking for the synthesized check.
        let source = r#"
            async fn auto(fd: i64, token: ref CancelToken) -> i64 {
              let n: i64 = io_recv_async(fd, 64);
              return n;
            }
            fn main() -> i64 { return 0; }
        "#;
        let c = crate::compile_to_c(source).expect("compiles");
        // The auto-injected guard reads through the Task struct's
        // token pointer field, so it emits roughly:
        //   if (((v___t)->token)->cancelled) { return -1; }
        // Looking for the cancelled-field read is a strong signal
        // even though the surrounding shape may vary.
        assert!(
            c.contains("->cancelled") || c.contains(".cancelled"),
            "A4.4 guard not visible in generated C; got:\n{}",
            c
        );
    }

    #[test]
    fn mut_ref_vec_index_compiles_and_types() {
        // A4.3 (2026-06-08): `mut ref vec[i]` is now accepted.
        // Result type is `RefMut(element_ty)`; both backends
        // lower it to a pointer into the Vec's data buffer.
        // This unlocks `__poll_X(mut ref pool[i])` over a
        // `Vec<Task__X>` — the load-bearing multi-task pattern.
        let source = r#"
            fn modify(slot: mut ref i64) -> i64 {
              return 0;
            }
            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2, 3);
              let _ = modify(mut ref xs[1]);
              return 0;
            }
        "#;
        crate::compile(source).expect("mut ref vec[i] compiles");
        crate::compile_to_c(source).expect("C backend accepts mut ref vec[i]");
        crate::compile_to_llvm(source).expect("LLVM backend accepts mut ref vec[i]");
    }

    #[test]
    fn mut_ref_vec_index_rejects_non_vec_source() {
        // The new arm requires the indexed binding to be a
        // Vec<T>. Indexing a non-Vec via `mut ref` surfaces a
        // helpful diagnostic.
        let source = r#"
            fn modify(slot: mut ref i64) -> i64 {
              return 0;
            }
            fn main() -> i64 {
              let n: i64 = 42;
              let _ = modify(mut ref n[0]);
              return 0;
            }
        "#;
        let err = crate::compile(source).expect_err("non-Vec source must be rejected");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("Vec") || combined.contains("vec"),
            "expected Vec-required diagnostic, got: {}",
            combined
        );
    }

    #[test]
    fn box_value_dyn_sugar_requires_iface_impl() {
        // The elaboration only fires when the concrete type
        // already `implement`s the iface; missing-impl case
        // surfaces a clear diagnostic that names both types.
        let source = r#"
            struct Circle { r: i64 }
            struct NotDrawable { x: i64 }
            interface Drawable { fn area(self: Circle) -> i64; }
            implement Drawable for Circle {
              fn area(self: Circle) -> i64 { return self.r; }
            }
            fn main() -> i64 {
              let n: NotDrawable = NotDrawable { x: 1 };
              let b: Box<dyn Drawable> = box(n);
              return 0;
            }
        "#;
        let err = crate::compile(source).expect_err("missing impl must be rejected");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("NotDrawable") && combined.contains("Drawable"),
            "expected impl-missing diagnostic that names both types, got: {}",
            combined
        );
    }

    #[test]
    fn box_rejects_unbox_of_non_copy_inner() {
        // The recursive-drop wiring stores the inner value's
        // pointer-state on the heap; `unbox(ref b)` would copy
        // that state out by value, aliasing the buffer the box
        // still owns. v1 rejects this with a diagnostic that
        // points users toward by-ref / struct-field usage.
        let source = r#"
            fn main() -> i64 {
              let xs: Vec<i64> = vec(1, 2, 3);
              let b: Box<Vec<i64>> = box(xs);
              let copied: Vec<i64> = unbox(ref b);
              return 0;
            }
        "#;
        let err = crate::compile(source).expect_err("unbox of non-Copy inner must be rejected");
        let combined = err.iter().map(|d| d.message.as_str()).collect::<Vec<_>>().join("\n");
        assert!(
            combined.contains("alias") || combined.contains("non-Copy"),
            "expected unbox-non-Copy diagnostic, got: {}",
            combined
        );
    }

