    // -----------------------------------------------------------------
    // Raw pointer types — `*const T` / `*mut T`
    // (Layer 1.1+ of unsafe.md; prerequisite for Layer 1.2's
    // no-escape dataflow).
    //
    // Same embedded gate as the `unsafe(reason = "...")` block:
    // hosted builds reject raw pointer types appearing in function
    // signatures, struct fields, or as cast targets;
    // `INTENT_TARGET_EMBEDDED=1` opens them.
    //
    // Casts permitted: `Ref(T) → Ptr(T)`, `RefMut(T) → PtrMut(T)`,
    // and the downgrade `RefMut(T) → Ptr(T)`. The mutability-
    // adding direction (`Ptr → PtrMut`) is intentionally rejected.
    // -----------------------------------------------------------------

    #[test]
    fn raw_ptr_in_signature_rejected_on_hosted() {
        let _guard = EmbeddedTargetGuard::hosted();
        let source = r#"
            fn dangler() -> *const i64 {
              let x: i64 = 42;
              return (ref x) as *const i64;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("raw ptr return rejected on hosted");
        assert!(
            errs.iter().any(|d| d.message.contains("raw pointer type")),
            "expected raw-ptr-on-hosted diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn raw_ptr_cast_target_rejected_on_hosted() {
        let _guard = EmbeddedTargetGuard::hosted();
        // No raw pointer in the signature — the only raw-ptr
        // appearance is the cast target. The gate at the cast
        // site still fires.
        let source = r#"
            fn dangler() -> i64 {
              let x: i64 = 42;
              let _p = (ref x) as *const i64;
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("raw ptr cast rejected on hosted");
        assert!(
            errs.iter().any(|d| d.message.contains("raw pointer type")),
            "expected raw-ptr-cast diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn raw_ptr_const_creation_compiles_on_embedded() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn take_ptr() -> i64 {
              let x: i64 = 42;
              let _p = (ref x) as *const i64;
              return 0;
            }
            fn main() -> i64 { return take_ptr(); }
        "#;
        let c = compile_to_c(source).expect("compiles to C on embedded gate");
        // `(ref x) as *const i64` lowers to `(const int64_t*)&v_x` in C.
        assert!(
            c.contains("(const int64_t*)") || c.contains("const int64_t*)("),
            "expected `const int64_t*` cast in C output, got:\n{}",
            c
        );
    }

    #[test]
    fn raw_ptr_mut_creation_compiles_on_embedded() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn take_mut_ptr() -> i64 {
              let x: i64 = 42;
              let _p = (mut ref x) as *mut i64;
              return 0;
            }
            fn main() -> i64 { return take_mut_ptr(); }
        "#;
        let c = compile_to_c(source).expect("compiles to C on embedded gate");
        assert!(
            c.contains("(int64_t*)") || c.contains("int64_t*)("),
            "expected `int64_t*` cast in C output, got:\n{}",
            c
        );
    }

    #[test]
    fn raw_ptr_llvm_emits_pointer_type() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn take_ptr() -> i64 {
              let x: i64 = 42;
              let _p = (ref x) as *const i64;
              return 0;
            }
            fn main() -> i64 { return take_ptr(); }
        "#;
        let ll = compile_to_llvm(source).expect("compiles to LLVM on embedded gate");
        // The Ref→Ptr cast emits no IR instruction (bitcast-noop);
        // the SSA value is the original `i64*` alloca pointer.
        // What we check: that compilation succeeded and the
        // function lowered without a panic. The cast's value
        // flows into `_p` which is then unused — LLVM still
        // allocates a slot for it.
        assert!(
            ll.contains("define"),
            "expected at least one fn definition in LLVM output, got:\n{}",
            ll
        );
    }

    #[test]
    fn raw_ptr_mut_to_const_downgrade_allowed() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn dual() -> i64 {
              let x: i64 = 42;
              let _p = (mut ref x) as *const i64;
              return 0;
            }
            fn main() -> i64 { return dual(); }
        "#;
        let _ = compile(source).expect("RefMut → Ptr downgrade compiles");
    }

    #[test]
    fn raw_ptr_const_to_mut_upgrade_rejected() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn upgrade() -> i64 {
              let x: i64 = 42;
              let p = (ref x) as *const i64;
              let _q = p as *mut i64;
              return 0;
            }
            fn main() -> i64 { return upgrade(); }
        "#;
        let errs = compile(source).expect_err("Ptr → PtrMut upgrade must be rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("cannot cast")),
            "expected `cannot cast` diagnostic, got: {:?}",
            errs
        );
    }

    // -----------------------------------------------------------------
    // Layer 1.2 — no-escape on `&local`-derived raw pointers
    // (unsafe.md § Layer 1.2). The dataflow rejects raw pointers
    // whose origin is a stack-local from being returned, stored
    // in a heap location (Vec slot, struct field), or otherwise
    // escaping the frame. Pointers derived from parameters are
    // not tainted (they came from outside the frame).
    // -----------------------------------------------------------------

    #[test]
    fn no_escape_rejects_return_of_local_ptr() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn dangler() -> *const i64 {
              let x: i64 = 42;
              return (ref x) as *const i64;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("returning local ptr must be rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("cannot be returned")),
            "expected no-escape return diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn no_escape_rejects_return_of_local_ptr_via_binding() {
        let _guard = EmbeddedTargetGuard::embedded();
        // Same pattern, but with the pointer flowing through a
        // let-binding before the return — the taint propagation
        // catches it.
        let source = r#"
            fn dangler() -> *const i64 {
              let x: i64 = 42;
              let p = (ref x) as *const i64;
              return p;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("returning local ptr via binding rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("cannot be returned")),
            "expected no-escape return diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn no_escape_allows_pass_through_of_param_ptr() {
        let _guard = EmbeddedTargetGuard::embedded();
        // Pointer parameter is already from outside the frame,
        // so returning it is fine.
        let source = r#"
            fn pass(p: *const i64) -> *const i64 {
              return p;
            }
            fn main() -> i64 { return 0; }
        "#;
        let _ = compile(source).expect("param ptr pass-through compiles");
    }

    #[test]
    fn no_escape_rejects_store_into_vec_of_local_ptr() {
        let _guard = EmbeddedTargetGuard::embedded();
        // The Vec slot would outlive the local's frame. The
        // store-into-heap escape catches it.
        // Note: Vec<*const T> would need the cast target check
        // to also gate at type-declaration time; this test
        // exercises the IndexAssign path instead via an array.
        let source = r#"
            fn bad(xs: mut ref [*const i64; 1]) {
              let x: i64 = 42;
              xs[0] = (ref x) as *const i64;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("store-into-heap rejected");
        // Either the no-escape diagnostic or a related rejection.
        // What we want to see: SOME diagnostic that calls out the
        // escape. (The exact wording depends on which gate fires
        // first; Layer 1.2's check is the desired one but the
        // raw-ptr-on-hosted gate at the param type might also
        // fire on the array element type. Both are correct
        // rejections.)
        assert!(
            !errs.is_empty(),
            "expected at least one diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn no_escape_allows_local_use_in_same_frame() {
        let _guard = EmbeddedTargetGuard::embedded();
        // The pointer is created, bound, and never escapes the
        // function. Valid.
        let source = r#"
            fn local_use() -> i64 {
              let x: i64 = 42;
              let _p = (ref x) as *const i64;
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let _ = compile(source).expect("local-only use compiles");
    }

    #[test]
    fn no_escape_rejects_mut_ptr_return() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn bad() -> *mut i64 {
              let x: i64 = 42;
              return (mut ref x) as *mut i64;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("mut ptr return rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("cannot be returned")),
            "expected no-escape return diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn no_escape_diagnostic_recommends_handle() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            fn dangler() -> *const i64 {
              let x: i64 = 42;
              return (ref x) as *const i64;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("rejection expected");
        // The diagnostic should mention `Handle<T>` / `Pool<T>`
        // (Layer 2) as the supported pattern. Helps users
        // discover the right primitive instead of trying to
        // work around the no-escape rule.
        assert!(
            errs.iter().any(|d| d.message.contains("Handle<T>")),
            "expected Handle<T> recommendation in diagnostic, got: {:?}",
            errs
        );
    }

    // -----------------------------------------------------------------
    // Layer 2.1a scaffolding — `Pool<T>` / `Handle<T>` types
    // parse and type-check. The builtins (`pool_new`,
    // `pool_alloc`, `pool_get`, `pool_free`) and the codegen
    // bundles land in Layers 2.1b and 2.1c. v1 restricts T to
    // i64 — the parser accepts any T but the codegen layer will
    // enforce the restriction once it lands.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 2.1b — `pool_new` / `pool_alloc` / `pool_get` /
    // `pool_free` builtin signatures (checker-only; codegen lands
    // in 2.1c). `compile()` runs the typechecker without invoking
    // backend emission, so these tests verify the signatures
    // without depending on the missing C / LLVM bundles.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 2.1c — Pool/Handle codegen end-to-end. Verify that
    // both backends emit the bundle and that programs touching
    // Pool / Handle compile to valid C / LLVM.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 2.2 — `Handle<T>` is the blessed escape from `unsafe`.
    //
    // Falls out of Layers 1.1 + 1.2 + 2: raw pointer types are
    // gated to the embedded target, raw pointers derived from
    // stack locals can't escape via return / heap store
    // (Layer 1.2), and `Handle<T>` is the Copy, generationally-
    // checked alternative for crossing function boundaries.
    //
    // No new code — these tests pin the standing position so
    // future refactors can't accidentally erode it.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 1.3 — `Tainted<T>` wrapper + `taint(v)` / `assert_safe(t)`
    // builtins. V1 restricts T to i64. The `*p` raw-pointer
    // deref operator (the canonical Tainted producer) is queued
    // as a follow-up; this commit ships the wrapper machinery
    // so the discipline is in place when deref lands.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 1.3 — `raw_load(p)` / `raw_store(p, v)` builtins.
    // The canonical Tainted producer: `raw_load` reads through a
    // raw pointer and wraps the value in `Tainted<T>`. `raw_store`
    // writes through a `*mut T`.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 3.1 — `unsafe_alloc(n)` / `unsafe_free(p)` builtins.
    // Heap allocation inside unsafe. The canary instrumentation
    // (debug-mode magic words around the allocation) is a
    // separate follow-up; this commit ships the raw allocator
    // first.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 3.1+ — canary instrumentation around unsafe_alloc /
    // unsafe_free. Each allocation gets a 24-byte overhead
    // (size + prefix-canary 0xDEADBEEFCAFEBABE + user bytes +
    // suffix-canary 0xBAADF00DDEADC0DE). `unsafe_free` verifies
    // both canaries and aborts on mismatch.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 3.2 — `BoundedPtr<T>` fat pointer. Wraps a raw
    // pointer with len/capacity for runtime bounds checks.
    // `bptr_get` returns `Option<i64>` (None on OOB); `bptr_set`
    // returns `bool` (false on OOB, no store performed).
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 5 v2 foundation — `Region` bump-allocator arena.
    // Affine; scope-exit drop frees the entire arena in one
    // `free` call. V1 scaffolding returns raw `*mut i64`; the
    // full Layer 5 `&'arena T` lifetime-tagged pointer
    // refinement is a substantial follow-up.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 5 lifetime-tagged — `ArenaRef<T>` + `region_borrow_i64`
    // + `aref_load` / `aref_store`. The no-escape pass (extended
    // from Layer 1.2) rejects ArenaRef return / heap-store when
    // the source Region is local. Zero runtime cost per deref.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Layer 5 — `region <name> { ... }` block syntax.
    // Sugar for `{ let <name>: Region = region_new(); <body>; }`
    // with the block boundary providing the natural scope-exit
    // drop. The no-escape dataflow on ArenaRef still fires.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // T1.1 — `intentc deviations` extractor. Walks the
    // `TypedStmt::UnsafeBlock { reason, ... }` nodes and emits
    // structured records (file, line, prefix, reason,
    // function, target_standard) in CSV / JSON / text formats.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // T1.2 — `#[no_heap]` attribute + INTENT_NO_HEAP=1 global mode.
    // MISRA C 2012 Rule 21.3 alignment. Functions marked
    // `#[no_heap]` (or every fn under the global mode) must not
    // transitively reach any heap-allocating builtin.
    // -----------------------------------------------------------------

    /// Compile a source string + run `enforce_no_heap` with an
    /// explicit `global` flag. Bypasses the env-var read in
    /// `compile()` (gated to `#[cfg(not(test))]`) so global-mode
    /// tests don't race with the other 1500+ tests running in
    /// parallel. The function returns the union of typecheck
    /// diagnostics and no_heap diagnostics — if either layer
    /// rejects, the combined result is an Err.
    fn compile_with_global_no_heap(
        source: &str,
        global: bool,
    ) -> Result<crate::checker::CheckedProgram, Vec<crate::diagnostic::Diagnostic>> {
        let mut diagnostics = Vec::new();
        let checked = compile(source)?;
        crate::safety::enforce_no_heap(&checked.ir, global, &mut diagnostics);
        if diagnostics.is_empty() {
            Ok(checked)
        } else {
            Err(diagnostics)
        }
    }

    // -----------------------------------------------------------------
    // T1.3 — Stack-depth bound checker (`intentc stack-depth`).
    // Per-function frame size estimate + call-graph traversal
    // for max depth per entry-point. Recursion handling:
    // `#[bounded(N)]` caps at N+1 frames; unbounded recursion
    // (direct or via cycle) is reported as UNBOUNDED.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // T2.3 — `#[no_float]` attribute. Function (and transitive
    // callees) must not use f32 / f64 anywhere — in signatures,
    // local bindings, expressions, or struct/tuple fields.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // T2.6 — pointer-arithmetic ban diagnostic (MISRA C 2012
    // Rule 18.4). Explicit MISRA-aware error message when
    // users try `+`/`-` / shift / bitwise on `*const T` /
    // `*mut T` operands. Comparison ops still allowed (== /
    // != on pointers is legitimate).
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // T2.2 — `#[interrupt]` calling convention. Composite that
    // expands to no_heap + no_recursion + no_lock + no_spawn.
    // ISR bodies cannot allocate, recurse, take a blocking
    // lock, or spawn worker threads / parallel-for.
    // -----------------------------------------------------------------

    // -----------------------------------------------------------------
    // Standard composites — `#[misra_c_2012]`, `#[asil_d]`,
    // `#[do178c_level_a]`, `#[iec_62304_class_c]`. Each
    // expands to a union of primitive constraints; v1 maps
    // all four to `{no_heap, no_recursion}` since the
    // additional primitives (`bounded_stack`, `wcet`,
    // `deterministic_timing`) are Tier 3 work. The composite
    // tag is preserved on the function so the deviations
    // extractor can label each record with the standard.
    // -----------------------------------------------------------------

    #[test]
    fn asil_d_composite_rejects_heap_alloc() {
        let source = r#"
            #[asil_d]
            fn bad() -> i64 {
              let v = vec(1, 2, 3);
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[asil_d] + vec() rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("heap-allocating")
                && d.message.contains("#[no_heap]")),
            "expected composite to expand to #[no_heap], got: {:?}",
            errs
        );
    }

    #[test]
    fn misra_c_2012_composite_rejects_recursion() {
        let source = r#"
            #[misra_c_2012]
            fn rec(n: i64) -> i64 {
              if n <= 0 { return 0; }
              return rec(n - 1) + 1;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[misra_c_2012] + recursion rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("recurses")
                && d.message.contains("#[no_recursion]")),
            "expected composite to expand to #[no_recursion], got: {:?}",
            errs
        );
    }

    #[test]
    fn composite_preserved_in_deviations_target_standard() {
        let _guard = EmbeddedTargetGuard::embedded();
        let source = r#"
            #[asil_d]
            fn critical() -> i64 {
              unsafe(reason = "MMIO: control register") {
                let _ = 0;
              }
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let checked = compile(source).expect("compiles under embedded gate");
        let mut map = crate::diagnostic::FileMap::new();
        map.push("<test>".to_string(), source.to_string(), 0);
        let devs = crate::deviations::extract_deviations(&checked.ir, &map);
        assert_eq!(devs.len(), 1);
        assert_eq!(devs[0].target_standard, "asil_d");
        assert_eq!(devs[0].function, "critical");
    }

    #[test]
    fn do178c_and_iec_62304_composites_recognized() {
        let source = r#"
            #[do178c_level_a]
            fn avionics(x: i64) -> i64 { return x; }
            #[iec_62304_class_c]
            fn medical(x: i64) -> i64 { return x; }
            fn main() -> i64 { return 0; }
        "#;
        let _ = compile(source).expect("both composites compile");
    }

    #[test]
    fn two_composite_tags_on_same_fn_rejected() {
        let source = r#"
            #[asil_d] #[misra_c_2012]
            fn double_tagged(x: i64) -> i64 { return x; }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("two composite tags rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("already tagged")),
            "expected double-tag diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn composite_plus_primitive_stacks() {
        // #[asil_d] expands to {no_heap, no_recursion}. Layering
        // #[no_float] on top should still compose — both apply.
        let source = r#"
            #[asil_d] #[no_float]
            fn strict(x: i64) -> i64 { return x + 1; }
            fn main() -> i64 { return 0; }
        "#;
        let _ = compile(source).expect("composite + primitive stacks");
    }

    #[test]
    fn interrupt_accepts_simple_isr() {
        let source = r#"
            #[interrupt]
            fn isr(x: i64) -> i64 { return x + 1; }
            fn main() -> i64 { return 0; }
        "#;
        let _ = compile(source).expect("#[interrupt] + pure body compiles");
    }

    #[test]
    fn interrupt_rejects_heap_alloc() {
        let source = r#"
            #[interrupt]
            fn bad() -> i64 {
              let v = vec(1, 2, 3);
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[interrupt] + vec() rejected");
        // The composite expansion sets `no_heap` so the no_heap
        // pass produces the diagnostic.
        assert!(
            errs.iter().any(|d| d.message.contains("heap-allocating")
                && d.message.contains("#[no_heap]")),
            "expected no_heap diagnostic from composite expansion, got: {:?}",
            errs
        );
    }

    #[test]
    fn interrupt_rejects_recursion() {
        let source = r#"
            #[interrupt]
            fn isr_rec(n: i64) -> i64 {
              if n <= 0 { return 0; }
              return isr_rec(n - 1) + 1;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[interrupt] + recursion rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("recurses")
                && d.message.contains("#[no_recursion]")),
            "expected no_recursion diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn interrupt_rejects_mutex_lock() {
        let source = r#"
            #[interrupt]
            fn isr_lock(m: mut ref Mutex<i64>) -> i64 {
              let g = mutex_lock(m);
              return guard_get(ref g);
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[interrupt] + mutex_lock rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("blocking lock acquire")
                && d.message.contains("#[interrupt]")),
            "expected ISR-framed lock diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn interrupt_rejects_task_spawn() {
        let source = r#"
            #[interrupt]
            fn isr_spawn() -> i64 {
              task worker {
                let _ = 0;
              }
              join worker;
              return 0;
            }
            fn main() -> i64 { return 0; }
        "#;
        let errs = compile(source).expect_err("#[interrupt] + task rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("`task` spawn")
                && d.message.contains("#[interrupt]")),
            "expected ISR-framed task diagnostic, got: {:?}",
            errs
        );
    }

