    // T3.5 of the safety-standard arc — MISRA 13.5 tightening.

    #[test]
    fn misra_13_5_rejects_impure_call_in_or_rhs() {
        let source = r#"
            fn might_have_effects(x: i64) -> bool { return x > 0; }
            #[misra_c_2012]
            fn classify(x: i64) -> bool {
              return x == 0 || might_have_effects(x);
            }
            fn main() -> i64 {
              if classify(0) { return 1; }
              return 0;
            }
        "#;
        let errs = compile(source).expect_err("impure call in || RHS rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("MISRA 13.5")),
            "expected MISRA 13.5 diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn misra_13_5_rejects_impure_call_in_and_rhs() {
        let source = r#"
            fn check(x: i64) -> bool { return x > 0; }
            #[asil_d]
            fn guarded(x: i64) -> bool {
              return x != 0 && check(x);
            }
            fn main() -> i64 {
              if guarded(0) { return 1; }
              return 0;
            }
        "#;
        let errs = compile(source).expect_err("impure call in && RHS rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("MISRA 13.5")),
            "expected MISRA 13.5 diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn misra_13_5_ok_for_pure_call_in_rhs() {
        let source = r#"
            pure fn safe(x: i64) -> bool { return x > 0; }
            #[misra_c_2012]
            fn guarded(x: i64) -> bool {
              return x != 0 && safe(x);
            }
            fn main() -> i64 {
              if guarded(5) { return 1; }
              return 0;
            }
        "#;
        let _ = compile(source).expect("pure-fn call in && RHS is allowed");
    }

    #[test]
    fn misra_13_5_ok_when_call_lifted_to_let() {
        let source = r#"
            fn might_effect(x: i64) -> bool { return x > 0; }
            #[misra_c_2012]
            fn guarded(x: i64) -> bool {
              let pre: bool = might_effect(x);
              return x != 0 && pre;
            }
            fn main() -> i64 {
              if guarded(5) { return 1; }
              return 0;
            }
        "#;
        let _ = compile(source).expect("lifted call OK in MISRA fn");
    }

    #[test]
    fn misra_13_5_does_not_fire_on_unannotated_fn() {
        let source = r#"
            fn might_effect(x: i64) -> bool { return x > 0; }
            fn no_annotation(x: i64) -> bool {
              return x != 0 && might_effect(x);
            }
            fn main() -> i64 {
              if no_annotation(5) { return 1; }
              return 0;
            }
        "#;
        let _ = compile(source).expect("unannotated fn not affected");
    }

    #[test]
    fn misra_13_5_fires_inside_nested_if() {
        let source = r#"
            fn helper(x: i64) -> bool { return x > 0; }
            #[do178c_level_a]
            fn complex(x: i64) -> bool {
              if x < 0 {
                return false;
              } else {
                return x == 0 || helper(x);
              }
            }
            fn main() -> i64 {
              if complex(5) { return 1; }
              return 0;
            }
        "#;
        let errs = compile(source).expect_err(
            "MISRA 13.5 should also fire in nested branches",
        );
        assert!(
            errs.iter().any(|d| d.message.contains("MISRA 13.5")),
            "expected MISRA 13.5 diagnostic, got: {:?}",
            errs
        );
    }

    // T3.4 of the safety-standard arc — #[deterministic_timing].

    #[test]
    fn deterministic_timing_ok_for_straightline_fn() {
        let source = r#"
            #[deterministic_timing]
            fn straight(x: i64) -> i64 {
              let a: i64 = x + 1;
              let b: i64 = a * 2;
              return b;
            }
            fn main() -> i64 { return straight(5); }
        "#;
        let _ = compile(source).expect("straight-line fn compiles");
    }

    #[test]
    fn deterministic_timing_rejects_while_loop() {
        let source = r#"
            #[deterministic_timing]
            fn loops(x: i64) -> i64 {
              let i: i64 = 0;
              while i < x { i = i + 1; }
              return i;
            }
            fn main() -> i64 { return loops(5); }
        "#;
        let errs = compile(source).expect_err("while rejected");
        assert!(
            errs.iter().any(|d| d.message.contains("deterministic_timing")
                && d.message.contains("while")),
            "expected while-loop diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn deterministic_timing_rejects_unequal_if_arms() {
        let source = r#"
            #[deterministic_timing]
            fn branch(x: i64) -> i64 {
              if x > 0 {
                let a: i64 = 1;
                let b: i64 = 2;
                let c: i64 = 3;
                return a + b + c;
              } else {
                return 0;
              }
            }
            fn main() -> i64 { return branch(5); }
        "#;
        let errs = compile(source).expect_err(
            "if-arms with different cycle counts rejected",
        );
        assert!(
            errs.iter().any(|d| d.message.contains("deterministic_timing")
                && d.message.contains("unequal")),
            "expected unequal-arms diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn deterministic_timing_ok_for_equal_arms() {
        let source = r#"
            #[deterministic_timing]
            fn branch(x: i64) -> i64 {
              if x > 0 {
                let a: i64 = 1;
                return a;
              } else {
                let b: i64 = 2;
                return b;
              }
            }
            fn main() -> i64 { return branch(5); }
        "#;
        let _ = compile(source).expect("equal-arm fn compiles");
    }

