    #[test]
    fn acyclicity_three_way_mutual_cycle() {
        let source = r#"
            fn a() -> i64 { return b(); }
            fn b() -> i64 { return c(); }
            fn c() -> i64 { return a(); }
            fn main() -> i64 { return a(); }
        "#;
        let checked = compile(source).expect("compiles");
        let report = crate::acyclicity::check_acyclicity(&checked.ir);
        assert_eq!(report.cycles.len(), 1);
        assert_eq!(report.cycles[0].members.len(), 3);
        assert!(report.has_violations());
    }

    // T3.2 of the safety-standard arc — #[wcet(cycles=N)].

    #[test]
    fn wcet_ok_when_within_budget() {
        let source = r#"
            #[wcet(cycles=100)]
            fn small() -> i64 {
              let a: i64 = 1;
              let b: i64 = 2;
              return a + b;
            }
            fn main() -> i64 { return small(); }
        "#;
        let _ = compile(source).expect("wcet within budget compiles");
    }

    #[test]
    fn wcet_rejects_unbounded_while() {
        let source = r#"
            #[wcet(cycles=1000)]
            fn loops() -> i64 {
              let i: i64 = 0;
              while i < 10 {
                i = i + 1;
              }
              return i;
            }
            fn main() -> i64 { return loops(); }
        "#;
        let errs = compile(source).expect_err("while loop must mark wcet UNBOUNDED");
        assert!(
            errs.iter().any(|d| d.message.contains("UNBOUNDED")
                && d.message.contains("wcet")),
            "expected UNBOUNDED diagnostic, got: {:?}",
            errs
        );
    }

    #[test]
    fn wcet_ok_for_const_bounded_for_loop() {
        let source = r#"
            #[wcet(cycles=2000)]
            fn loops() -> i64 {
              let s: i64 = 0;
              for i from 0 to 10 {
                s = s + i;
              }
              return s;
            }
            fn main() -> i64 { return loops(); }
        "#;
        let _ = compile(source).expect(
            "for loop with const bounds + sufficient budget compiles",
        );
    }

